// Auto-generated from frontend/scripts/buildTeamLogos.mjs.
// Inlines each IPL team logo as a base64 data URL so the ShareCard
// rasterizer (html-to-image -> JPEG) embeds the crest without a
// runtime fetch. Mirrors the JAFFA logo pattern.
//
// Re-run `node scripts/buildTeamLogos.mjs` from frontend/ whenever
// the source PNGs in ../Logos/ change.

export const TEAM_LOGO_DATA_URLS: Record<string, string> = {
  CSK: "data:image/png;base64,",
  MI: "data:image/png;base64,",
  KKR: "data:image/png;base64,",
  RCB: "data:image/png;base64,",
  RR: "data:image/png;base64,",
  DC: "data:image/png;base64,",
  PBKS: "data:image/png;base64,",
  SRH: "data:image/png;base64,",
  LSG: "data:image/png;base64,",
  GT: "data:image/png;base64,",
};

export function getTeamLogoDataUrl(short: string | null | undefined): string | null {
  if (!short) return null;
  return TEAM_LOGO_DATA_URLS[short.toUpperCase()] || null;
}
